package ca.jarvis.bridge;

import android.app.Activity;
import android.content.ClipData;
import android.content.ContentValues;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import android.net.Uri;
import android.os.Build;
import android.os.Environment;
import android.provider.MediaStore;

import java.io.OutputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Direct local handoff for the SVG generated by the explicit "SVG" test bubble.
 *
 * The Gmail send+label operation must have succeeded BEFORE this is invoked.
 * This avoids starting multiple transparent MainActivity Gmail readers for a
 * file that this Activity already has in memory.
 *
 * No laser parameters, modes, motion or machine actions are touched.
 */
final class JarvisTestSvgLocalHandoff {
    private static final int MAX_SVG_BYTES = 5_000_000;

    private JarvisTestSvgLocalHandoff() { }

    static Uri saveAndOpen(Activity activity, String filename, byte[] svg)
            throws Exception {
        JarvisFileRouter.requireSvgForXtool(
                filename, "image/svg+xml", svg, MAX_SVG_BYTES);
        if (Build.VERSION.SDK_INT < 29)
            throw new Exception("Android 10 ou plus récent requis");

        ContentValues values = new ContentValues();
        values.put(MediaStore.Downloads.DISPLAY_NAME, filename);
        values.put(MediaStore.Downloads.MIME_TYPE, "image/svg+xml");
        values.put(MediaStore.Downloads.RELATIVE_PATH,
                Environment.DIRECTORY_DOWNLOADS + "/JarvisBridge");
        values.put(MediaStore.Downloads.IS_PENDING, 1);

        Uri uri = activity.getContentResolver().insert(
                MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
        if (uri == null) throw new Exception("Impossible de créer le SVG local");

        boolean written = false;
        try {
            try (OutputStream output = activity.getContentResolver().openOutputStream(uri)) {
                if (output == null) throw new Exception("Impossible d'écrire le SVG local");
                output.write(svg);
            }
            ContentValues ready = new ContentValues();
            ready.put(MediaStore.Downloads.IS_PENDING, 0);
            activity.getContentResolver().update(uri, ready, null, null);
            written = true;

            openInXtool(activity, uri);
            activity.getSharedPreferences("jarvis_bridge", Activity.MODE_PRIVATE)
                    .edit().putString("last_svg", uri.toString()).apply();
            return uri;
        } catch (Exception error) {
            if (!written) {
                try { activity.getContentResolver().delete(uri, null, null); }
                catch (RuntimeException ignored) { }
            }
            throw error;
        }
    }

    private static void openInXtool(Activity activity, Uri uri) throws Exception {
        PackageManager pm = activity.getPackageManager();
        String[] mimes = {
                "image/svg+xml", "application/octet-stream",
                "application/xml", "text/xml", "*/*"
        };
        Intent xToolIntent = null;
        List<Intent> safeViewers = new ArrayList<>();

        for (String mime : mimes) {
            Intent probe = viewIntent(activity, uri, mime);
            List<ResolveInfo> handlers = pm.queryIntentActivities(
                    probe, PackageManager.MATCH_DEFAULT_ONLY);
            for (ResolveInfo handler : handlers) {
                if (handler.activityInfo == null) continue;
                String pkg = handler.activityInfo.packageName;
                String klass = handler.activityInfo.name;
                if (pkg == null || klass == null) continue;
                String lower = pkg.toLowerCase(Locale.ROOT);
                String label = String.valueOf(handler.loadLabel(pm))
                        .toLowerCase(Locale.ROOT);
                if (lower.equals("ca.jarvis.bridge")
                        || lower.startsWith("ca.jarvis.bridge.")
                        || label.startsWith("jarvis bridge")) continue;

                Intent explicit = new Intent(probe);
                explicit.setClassName(pkg, klass);
                if (lower.contains("xtool") || label.contains("xtool")
                        || "com.makeblock.xcs".equals(lower)) {
                    xToolIntent = explicit;
                    break;
                }
                if ("image/svg+xml".equals(mime)) safeViewers.add(explicit);
            }
            if (xToolIntent != null) break;
        }

        if (xToolIntent != null) {
            activity.startActivity(xToolIntent);
            return;
        }

        // Use the same Android default-association fallback that has previously
        // opened SVGs correctly on the user's Samsung.
        Intent standard = viewIntent(activity, uri, "image/svg+xml");
        ResolveInfo defaultHandler = pm.resolveActivity(
                standard, PackageManager.MATCH_DEFAULT_ONLY);
        if (defaultHandler != null && defaultHandler.activityInfo != null) {
            String pkg = defaultHandler.activityInfo.packageName;
            String label = String.valueOf(defaultHandler.loadLabel(pm))
                    .toLowerCase(Locale.ROOT);
            if (pkg != null && (pkg.equals("ca.jarvis.bridge")
                    || pkg.startsWith("ca.jarvis.bridge.")
                    || label.startsWith("jarvis bridge"))) {
                throw new Exception("Association SVG vers Jarvis: boucle bloquée");
            }
        }
        if (defaultHandler == null && safeViewers.isEmpty()) {
            throw new Exception("Aucun lecteur SVG externe détecté");
        }
        activity.startActivity(standard);
    }

    private static Intent viewIntent(Activity activity, Uri uri, String mime) {
        Intent intent = new Intent(Intent.ACTION_VIEW);
        intent.setDataAndType(uri, mime);
        intent.setClipData(ClipData.newUri(
                activity.getContentResolver(), "Jarvis SVG", uri));
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        return intent;
    }
}
